import { readFile, writeFile } from 'node:fs/promises'

const skill = await readFile(new URL('../skills/remembering/SKILL.md', import.meta.url), 'utf8')
const target = new URL('../src/memory/generated.ts', import.meta.url)
const expected =
  '// Generated by tools/gen-memory-assets.mjs; edit skills/remembering/SKILL.md.\n// biome-ignore format: preserve canonical Skill source\nexport const rememberingSkill = ' +
  JSON.stringify(skill) +
  '\n'
let actual
try {
  actual = await readFile(target, 'utf8')
} catch (error) {
  if (error.code !== 'ENOENT') throw error
}
if (process.argv.includes('--write')) await writeFile(target, expected)
else if (actual !== expected)
  throw new Error('Remembering Skill asset is stale; run pnpm --filter @agnes/base gen')
